def linear_search(items, target):
    for idx, val in enumerate(items):
        if val == target:
            return idx
    return -1

print("Found at index:", linear_search([10, 20, 30], 20))

def binary_search(arr, target):
    low, high = 0, len(arr) - 1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

primes = [2, 3, 5, 7, 11, 13, 17]
print("Index of 11:", binary_search(primes, 11))

# Counting comparison steps in linear search
def count_linear_steps(items, target):
    steps = 0
    for x in items:
        steps += 1
        if x == target:
            break
    return steps

print("Steps to find 50 in 1..100:", count_linear_steps(range(1, 101), 50))

